//go:build amd64 && !appengine && !noasm && !purego && gc

package zstd

import "github.com/vahid-sohrabloo/fastzstd/internal/cpu"

// useHcAsm selects the assembly hash-chain lazy parser (lazyHc*).
var useHcAsm bool

func init() {
	cpu.RegisterAsm("hc", &useHcAsm, func() bool { return true })
}

// The lazy parser and hash-chain match finder specialised per mls, in
// hc_lazy_amd64.s (generated by gen_row_amd64.go, see row_amd64.go).
// lazyHcM runs compressBlockLazyGeneric's match loop for the block set up
// in p by hcAsmSetup (see lazyHcRun for the preconditions); hcSearchM is
// its register-convention finder (never called from Go).

//go:noescape
func lazyHc4(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
func hcSearch4()

//go:noescape
func lazyHc5(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
func hcSearch5()

//go:noescape
func lazyHc6(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
func hcSearch6()
